#!/usr/bin/env python3
# Generated By: OpenCode (rits/deepseek-ai/DeepSeek-V4.1-Flash-1017)
"""Refresh an OpenCode provider's model list from its /v1/models endpoint.

OpenCode reads model metadata from models.dev for known providers and from the
``models`` map under a provider entry for everything else. This script refreshes
that map: it fetches the provider's model list, keeps the newest version of each
model class, and writes a config fragment the repository reconciles into
``~/.config/opencode/opencode.json``.

Metadata the endpoint cannot supply (``limit``, ``cost``, ``reasoning``) is
carried over from the existing entry for model IDs that survive the refresh.
"""

import argparse
import copy
import json
import os
import re
import sys
import tempfile
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parent.parent
DEFAULT_FRAGMENT = ROOT / "opencode" / "opencode.json.d" / "15-models.json"

_FIRST_DIGIT = re.compile(r"\d")
_BUILD_SUFFIX = re.compile(r"-\d{3,}$")
_OPENAI_MODEL = re.compile(r"^(?:(?:gpt|chatgpt|codex)(?:$|[-_.])|o\d)", re.I)

RESPONSES_PACKAGE = "@opencode/ai/providers/openai-compatible/responses"


class RefreshError(Exception):
    """A provider or config problem that should be reported to the user."""


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    # A bearer token must not follow a redirect to an unexpected host.
    def redirect_request(
        self,
        req: urllib.request.Request,
        fp: Any,
        code: int,
        msg: str,
        headers: Any,
        newurl: str,
    ) -> None:
        return None


def models_url(base_url: str) -> str:
    """Build the model-list URL from an OpenAI-compatible base URL."""
    parts = urllib.parse.urlsplit(base_url.strip())
    if not parts.scheme or not parts.netloc:
        raise RefreshError(f"Not an absolute URL: {base_url!r}")

    path = parts.path.rstrip("/")
    if not path.endswith("/v1"):
        path = f"{path}/v1"
    path = f"{path}/models"

    query = urllib.parse.urlencode({"limit": "1000"})
    return urllib.parse.urlunsplit((parts.scheme, parts.netloc, path, query, ""))


def auth_headers(*, token: str | None, auth: str, api_version: str | None) -> dict[str, str]:
    """Return the credential headers for one request.

    ``api-key`` sends ``x-api-key`` for Anthropic-style providers. ``bearer``
    sends ``Authorization`` once, and never both headers.
    """
    if not token:
        raise RefreshError(
            "No provider credential. Set OPENAI_API_KEY, pass --token, or use "
            "--auth api-key with ANTHROPIC_API_KEY."
        )
    headers = {"accept": "application/json"}
    if auth == "api-key":
        headers["x-api-key"] = token
    else:
        headers["Authorization"] = f"Bearer {token}"
    if api_version:
        headers["anthropic-version"] = api_version
    return headers


def fetch_models(url: str, *, headers: dict[str, str], timeout: float) -> list[Any]:
    """Fetch and validate the provider's model list."""
    request = urllib.request.Request(url, headers=headers, method="GET")
    opener = urllib.request.build_opener(_NoRedirect)
    try:
        with opener.open(request, timeout=timeout) as response:
            payload = json.load(response)
    except urllib.error.HTTPError as error:
        raise RefreshError(f"Provider returned HTTP {error.code} for {url}") from error
    except (urllib.error.URLError, TimeoutError, json.JSONDecodeError) as error:
        raise RefreshError(f"Could not read models from {url}: {error}") from error

    data = payload.get("data") if isinstance(payload, dict) else None
    if not isinstance(data, list):
        raise RefreshError(f"Provider response has no data array: {url}")
    return data


def model_class(model_id: str) -> tuple[str, str]:
    """Split a model ID into its non-numeric prefix and its version."""
    match = _FIRST_DIGIT.search(model_id)
    if match is None:
        return model_id, ""
    index = match.start()
    return model_id[:index], model_id[index:]


def _version_key(version: str) -> tuple[tuple[int, int | str], ...]:
    """Compare versions component-wise, numerically when a component is a number."""
    key: list[tuple[int, int | str]] = []
    for part in version.replace("-", ".").split("."):
        if part.isdigit():
            key.append((1, int(part)))
        elif part:
            key.append((0, part.lower()))
    return tuple(key)


def latest_by_class(model_ids: list[str]) -> list[str]:
    """Keep only the highest version for each model class, in input order."""
    latest: dict[str, str] = {}
    order: list[str] = []
    for model_id in model_ids:
        prefix, version = model_class(model_id)
        current = latest.get(prefix)
        if current is None:
            latest[prefix] = model_id
            order.append(prefix)
            continue
        _, current_version = model_class(current)
        if _version_key(version) > _version_key(current_version):
            latest[prefix] = model_id
    return [latest[prefix] for prefix in order]


def generate_name(model_id: str) -> str:
    """Build a short name from a model ID: provider path and build number removed."""
    name = _BUILD_SUFFIX.sub("", model_id.rsplit("/", 1)[-1])
    parts: list[str] = []
    for token in name.replace("_", "-").split("-"):
        if token and token.isdigit() and parts and parts[-1].isdigit():
            parts[-1] = f"{parts[-1]}.{token}"
        elif token:
            parts.append(token)
    return " ".join(parts) or model_id


def model_ids(entries: list[Any]) -> list[str]:
    """Return unique, non-empty model IDs in provider order."""
    ids: list[str] = []
    seen: set[str] = set()
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        model_id = entry.get("id")
        if not isinstance(model_id, str):
            continue
        model_id = model_id.strip()
        if not model_id or model_id in seen:
            continue
        seen.add(model_id)
        ids.append(model_id)
    return ids


def display_names(entries: list[Any]) -> dict[str, str]:
    """Map model ID to the provider's display name, when it differs."""
    names: dict[str, str] = {}
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        model_id = entry.get("id")
        display_name = entry.get("display_name")
        if not isinstance(model_id, str) or not isinstance(display_name, str):
            continue
        label = display_name.strip()
        if label and label != model_id.strip():
            names[model_id.strip()] = label
    return names


def is_openai_model(model_id: str) -> bool:
    """True for OpenAI-branded IDs, which OpenCode must call via /responses."""
    return bool(_OPENAI_MODEL.match(model_id.rsplit("/", 1)[-1]))


def build_models(
    entries: list[Any],
    *,
    existing: dict[str, Any] | None = None,
    latest_only: bool = False,
) -> dict[str, dict]:
    """Convert provider model records into an OpenCode ``models`` map.

    Entries already present in ``existing`` keep their metadata, so a refresh
    does not discard limits or costs the endpoint cannot report. Every ID the
    endpoint reports is kept unless ``latest_only`` is set; the family heuristic
    treats everything before the first digit as one class, so it also collapses
    distinct models such as ``gpt-4o`` and ``gpt-4o-mini``.
    """
    existing = existing or {}
    names = display_names(entries)
    ids = model_ids(entries)
    if not ids:
        raise RefreshError("Provider returned no usable models")
    if latest_only:
        ids = latest_by_class(ids)

    models: dict[str, dict] = {}
    for model_id in ids:
        row: dict[str, Any] = {}
        previous = existing.get(model_id)
        if isinstance(previous, dict):
            row.update(previous)
        row["name"] = names.get(model_id) or generate_name(model_id)
        if is_openai_model(model_id):
            row["package"] = RESPONSES_PACKAGE
        models[model_id] = row
    return models


def load_json(path: Path) -> dict:
    """Read a JSON object, tolerating the repository fragments' // comments."""
    if not path.exists():
        return {}
    text = path.read_text(encoding="utf-8")
    uncommented = "\n".join(
        line for line in text.splitlines() if not line.lstrip().startswith("//")
    )
    try:
        loaded = json.loads(uncommented)
    except json.JSONDecodeError as error:
        raise RefreshError(f"Invalid JSON in {path}: {error}") from error
    if not isinstance(loaded, dict):
        raise RefreshError(f"Config file is not a JSON object: {path}")
    return loaded


def provider_entry(config: dict, provider_id: str) -> dict:
    """Return the provider entry from either config shape, or an empty object."""
    for shape in ("providers", "provider"):
        group = config.get(shape)
        if isinstance(group, dict):
            entry = group.get(provider_id)
            if isinstance(entry, dict):
                return entry
    return {}


def existing_models(config: dict, provider_id: str) -> dict[str, Any]:
    models = provider_entry(config, provider_id).get("models")
    return models if isinstance(models, dict) else {}


def provider_base_url(config: dict, provider_id: str) -> str | None:
    """Return the provider's base URL from its settings, then its options."""
    entry = provider_entry(config, provider_id)
    for key in ("settings", "options"):
        group = entry.get(key)
        if isinstance(group, dict):
            base_url = group.get("baseURL")
            if isinstance(base_url, str) and base_url.strip():
                return base_url
    return None


def provider_api_key(config: dict, provider_id: str) -> str | None:
    """Return the provider's configured key, resolving OpenCode's {env:VAR}."""
    entry = provider_entry(config, provider_id)
    for key in ("settings", "options"):
        group = entry.get(key)
        if not isinstance(group, dict):
            continue
        api_key = group.get("apiKey")
        if not isinstance(api_key, str) or not api_key.strip():
            continue
        api_key = api_key.strip()
        if api_key.startswith("{env:") and api_key.endswith("}"):
            return os.environ.get(api_key[5:-1].strip()) or None
        return api_key
    return None


def provider_env_names(config: dict, provider_id: str) -> list[str]:
    """Return the environment variables the provider declares for its key."""
    names = provider_entry(config, provider_id).get("env")
    if not isinstance(names, list):
        return []
    return [name for name in names if isinstance(name, str) and name.strip()]


def describe_missing_url(config_path: Path, config: dict, provider_id: str) -> str:
    """Explain where the base URL was looked for and what the config holds."""
    found = {
        shape: sorted(config[shape])
        for shape in ("providers", "provider")
        if isinstance(config.get(shape), dict)
    }
    if not config_path.exists():
        return (
            f"{config_path} does not exist, so no settings.baseURL was found for "
            f"{provider_id!r}; pass --url or set OPENAI_BASE_URL"
        )
    if not found:
        return (
            f"{config_path} has no 'providers' or 'provider' key, so no "
            f"settings.baseURL was found for {provider_id!r}; pass --url or set "
            "OPENAI_BASE_URL"
        )
    if not provider_entry(config, provider_id):
        return (
            f"{config_path} has no provider {provider_id!r} (found: "
            f"{found}); pass --url or set OPENAI_BASE_URL"
        )
    return (
        f"{config_path} declares {provider_id!r} but its settings.baseURL is "
        "unset; pass --url or set OPENAI_BASE_URL"
    )


def fragment(provider_id: str, models: dict[str, dict], *, shape: str) -> dict:
    """Return a fragment that merges this provider's models into the config."""
    return {shape: {provider_id: {"models": models}}}


def replace_models(config: dict, provider_id: str, models: dict[str, dict]) -> dict:
    """Return the config with this provider's models map replaced outright."""
    updated = copy.deepcopy(config)
    shape = "providers" if isinstance(updated.get("providers"), dict) else "provider"
    updated[shape][provider_id]["models"] = models
    return updated


def _has_comments(path: Path) -> bool:
    """True when the file carries full-line // comments an in-place write loses."""
    return any(
        line.lstrip().startswith("//")
        for line in path.read_text(encoding="utf-8").splitlines()
    )


def _write_json(path: Path, data: dict) -> None:
    """Write JSON atomically, preserving an existing file's permissions."""
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = path.stat().st_mode & 0o777 if path.exists() else None
    handle = tempfile.NamedTemporaryFile(
        "w",
        dir=path.parent,
        prefix=f".{path.name}.",
        delete=False,
        encoding="utf-8",
    )
    try:
        with handle:
            json.dump(data, handle, indent=2)
            handle.write("\n")
        if mode is not None:
            os.chmod(handle.name, mode)
        os.replace(handle.name, path)
    except BaseException:
        Path(handle.name).unlink(missing_ok=True)
        raise


def default_config_path() -> Path:
    """The live OpenCode config, updated in place unless --output is given."""
    opencode_dir = os.environ.get("OPENCODE_DIR")
    root = Path(opencode_dir) if opencode_dir else Path.home() / ".config" / "opencode"
    return root / "opencode.json"


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description=(
            "Replace an OpenCode provider's models map with the model list its "
            "/v1/models endpoint reports."
        )
    )
    parser.add_argument(
        "--provider",
        required=True,
        help="Provider ID as it appears in opencode.json",
    )
    parser.add_argument(
        "--url",
        help=(
            "Provider base URL (default: the provider entry's settings.baseURL, "
            "then $OPENAI_BASE_URL)"
        ),
    )
    parser.add_argument(
        "--token",
        help=(
            "Provider token (default: the provider's settings.apiKey, then the "
            "variable named in its env list, then $OPENAI_API_KEY)"
        ),
    )
    parser.add_argument(
        "--auth",
        choices=("bearer", "api-key"),
        default="bearer",
        help="Credential header (default: bearer)",
    )
    parser.add_argument(
        "--config",
        type=Path,
        help=(
            "Config file to update in place "
            "(default: $OPENCODE_DIR/opencode.json, then ~/.config/opencode/opencode.json)"
        ),
    )
    parser.add_argument(
        "--output",
        type=Path,
        help=(
            "Write a config fragment here instead of updating --config "
            f"(that is, {DEFAULT_FRAGMENT})"
        ),
    )
    parser.add_argument(
        "--shape",
        choices=("providers", "provider"),
        default="providers",
        help="Config key to emit with --output (default: providers)",
    )
    parser.add_argument(
        "--latest-only",
        action="store_true",
        help=(
            "Keep only the newest version of each family (everything before the "
            "first digit); collapses gpt-4o and gpt-4o-mini, so it is off by default"
        ),
    )
    parser.add_argument(
        "--timeout",
        type=float,
        default=20.0,
        help="Request timeout in seconds (default: 20)",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Print the result without writing it",
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)

    config_path = args.config or default_config_path()
    try:
        if not args.output and not config_path.exists():
            raise RefreshError(
                f"{config_path} does not exist; nothing to update. Pass --config "
                "or --output"
            )
        config = load_json(config_path)
        entry = provider_entry(config, args.provider)
        if not entry and not args.output:
            raise RefreshError(
                f"{config_path} has no provider {args.provider!r}; add the "
                "provider entry first, or pass --output for a fragment"
            )

        base_url = args.url or provider_base_url(config, args.provider)
        if not base_url:
            base_url = os.environ.get("OPENAI_BASE_URL")
        if not base_url:
            raise RefreshError(
                describe_missing_url(config_path, config, args.provider)
            )

        token = args.token or provider_api_key(config, args.provider)
        if token is None:
            for name in provider_env_names(config, args.provider):
                token = os.environ.get(name)
                if token:
                    break
        if token is None:
            token = os.environ.get(
                "ANTHROPIC_API_KEY" if args.auth == "api-key" else "OPENAI_API_KEY"
            )
        if not token:
            declared = ", ".join(
                f"${name}" for name in provider_env_names(config, args.provider)
            ) or "$OPENAI_API_KEY"
            raise RefreshError(
                f"no credential for {args.provider!r}: pass --token, set one of "
                f"{declared} (the provider's env list), or add settings.apiKey "
                f"in {config_path}"
            )

        models = build_models(
            fetch_models(
                models_url(base_url),
                headers=auth_headers(
                    token=token,
                    auth=args.auth,
                    api_version="2023-06-01" if args.auth == "api-key" else None,
                ),
                timeout=args.timeout,
            ),
            existing=existing_models(config, args.provider),
            latest_only=args.latest_only,
        )
        if args.output:
            result = fragment(args.provider, models, shape=args.shape)
            destination = args.output
        else:
            if _has_comments(config_path):
                raise RefreshError(
                    f"{config_path} carries // comments that an in-place write "
                    "would drop; write a fragment with --output and reconcile it"
                )
            result = replace_models(config, args.provider, models)
            destination = config_path
    except RefreshError as error:
        print(f"refresh-models: {error}", file=sys.stderr)
        return 1

    if args.dry_run:
        print(json.dumps(result, indent=2))
        return 0

    try:
        _write_json(destination, result)
    except OSError as error:
        print(f"refresh-models: {error}", file=sys.stderr)
        return 1

    print(f"Replaced {len(models)} models for {args.provider} in {destination}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
